function FooterModern() {
  const links = {
    Product: ['Features', 'Pricing', 'Integrations', 'Changelog'],
    Company: ['About', 'Blog', 'Careers', 'Press'],
    Resources: ['Documentation', 'Help Center', 'Community', 'API'],
    Legal: ['Privacy', 'Terms', 'Security', 'Cookies']
  };

  return (
    <footer className="bg-gray-900 text-white">
      <div className="max-w-7xl mx-auto px-6 py-16">
        <div className="grid grid-cols-2 md:grid-cols-6 gap-8 mb-12">
          {/* Brand */}
          <div className="col-span-2">
            <h3 className="text-2xl font-bold mb-4">Brand</h3>
            <p className="text-gray-400 mb-6 max-w-xs">Building the future of work, one feature at a time.</p>
            {/* Newsletter */}
            <div className="flex gap-2">
              <input type="email" placeholder="Enter your email" className="flex-1 px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-sm focus:outline-none focus:border-blue-500" />
              <button className="px-4 py-2 bg-blue-600 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors">Subscribe</button>
            </div>
          </div>
          {/* Links */}
          {Object.entries(links).map(([title, items]) => (
            <div key={title}>
              <h4 className="font-semibold mb-4">{title}</h4>
              <ul className="space-y-3">
                {items.map(item => (
                  <li key={item}><a href="#" className="text-gray-400 hover:text-white transition-colors text-sm">{item}</a></li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        {/* Bottom */}
        <div className="pt-8 border-t border-gray-800 flex flex-col md:flex-row items-center justify-between gap-4">
          <p className="text-gray-400 text-sm">© 2024 Brand. All rights reserved.</p>
          <div className="flex items-center gap-4">
            {['Twitter', 'GitHub', 'LinkedIn'].map(social => (
              <a key={social} href="#" className="text-gray-400 hover:text-white transition-colors text-sm">{social}</a>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
}

function FooterMinimal() {
  return (
    <footer className="bg-white border-t border-gray-100">
      <div className="max-w-7xl mx-auto px-6 py-8">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-6">
            <span className="font-bold text-gray-900">Brand</span>
            {['About', 'Privacy', 'Terms'].map(link => (
              <a key={link} href="#" className="text-gray-600 hover:text-gray-900 text-sm transition-colors">{link}</a>
            ))}
          </div>
          <p className="text-gray-500 text-sm">© 2024 Brand. All rights reserved.</p>
        </div>
      </div>
    </footer>
  );
}
